23	const (
24		maxRSSItemCount      = 100
25		defaultCacheDuration = 1 * time.Hour
26		maxCacheSize         = 50 // Maximum number of cached feeds
27	)
28	
29	var (
30		// Regex to match markdown headings at the start of a line.
31		markdownHeadingRegex = regexp.MustCompile(`^#{1,6}\s*`)
32	)
33	
34	// cacheEntry represents a cached RSS feed with expiration.
35	type cacheEntry struct {
36		content      string
37		etag         string
38		lastModified time.Time
39		createdAt    time.Time
40	}
41	
42	type RSSService struct {
43		Profile         *profile.Profile
44		Store           *store.Store
45		MarkdownService markdown.Service
46	
47		// Cache for RSS feeds
48		cache      map[string]*cacheEntry
49		cacheMutex sync.RWMutex
50	}
