58	func NewRSSService(profile *profile.Profile, store *store.Store, markdownService markdown.Service) *RSSService {
59		return &RSSService{
60			Profile:         profile,
61			Store:           store,
62			MarkdownService: markdownService,
63			cache:           make(map[string]*cacheEntry),
64		}
